import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Event Subscribers","description":"","frontmatter":{},"headers":[],"relativePath":"events/event-subscribers.md","filePath":"events/event-subscribers.md"}`),a={name:`events/event-subscribers.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="event-subscribers" tabindex="-1">Event Subscribers <a class="header-anchor" href="#event-subscribers" aria-label="Permalink to “Event Subscribers”">​</a></h1><p>An <strong>event subscriber</strong> is an AL procedure that listens for a particular event and executes its code when that event is raised.</p><p>Event subscribers are normally placed inside codeunits.</p><h2 id="creating-an-event-subscriber" tabindex="-1">Creating an Event Subscriber <a class="header-anchor" href="#creating-an-event-subscriber" aria-label="Permalink to “Creating an Event Subscriber”">​</a></h2><p>We use the <code>[EventSubscriber]</code> attribute to subscribe to an event.</p><p>Example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50101 CustomerEventSubscriber</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [EventSubscriber(</span></span>
<span class="line"><span>        ObjectType::Codeunit,</span></span>
<span class="line"><span>        Codeunit::CustomerEvents,</span></span>
<span class="line"><span>        &#39;OnCustomerCreated&#39;,</span></span>
<span class="line"><span>        &#39;&#39;,</span></span>
<span class="line"><span>        false,</span></span>
<span class="line"><span>        false)]</span></span>
<span class="line"><span>    local procedure HandleCustomerCreated(CustomerNo: Code[20])</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;Customer %1 was created.&#39;, CustomerNo);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This subscriber listens to the <code>OnCustomerCreated</code> event published by our <code>CustomerEvents</code> codeunit.</p><p>When that event is raised, <code>HandleCustomerCreated()</code> executes.</p><h2 id="understanding-eventsubscriber-parameters" tabindex="-1">Understanding EventSubscriber Parameters <a class="header-anchor" href="#understanding-eventsubscriber-parameters" aria-label="Permalink to “Understanding EventSubscriber Parameters”">​</a></h2><p>The <code>[EventSubscriber]</code> attribute accepts six arguments:</p><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>ObjectType</code></td><td>Type of object publishing the event.</td></tr><tr><td><code>ObjectId</code></td><td>ID or name of the object publishing the event.</td></tr><tr><td><code>EventName</code></td><td>Name of the published event.</td></tr><tr><td><code>ElementName</code></td><td>Field name for applicable table trigger events; otherwise, usually empty (<code>&#39;&#39;</code>).</td></tr><tr><td><code>SkipOnMissingLicense</code></td><td>Whether to skip the subscriber if the required license is missing.</td></tr><tr><td><code>SkipOnMissingPermission</code></td><td>Whether to skip the subscriber if the required permission is missing.</td></tr></tbody></table><p><strong>Note:</strong> Using <code>true</code> for either skip parameter means the subscriber is skipped when the corresponding requirement is missing. Using <code>false</code> causes an error instead.</p><h2 id="important-things-to-remember" tabindex="-1">Important Things to Remember <a class="header-anchor" href="#important-things-to-remember" aria-label="Permalink to “Important Things to Remember”">​</a></h2><ul><li>Event subscribers are normally defined inside codeunits.</li><li>A subscriber must reference the correct publisher object and event name.</li><li>The subscriber&#39;s parameters must match the publisher&#39;s event parameters.</li><li>Multiple subscribers can listen to the same event.</li><li>Subscribers execute when the corresponding event is raised.</li><li>You cannot specify the execution order of multiple subscribers.</li><li>Subscribers are commonly declared as <code>local procedure</code>.</li></ul><h2 id="subscribing-to-standard-business-central-events" tabindex="-1">Subscribing to Standard Business Central Events <a class="header-anchor" href="#subscribing-to-standard-business-central-events" aria-label="Permalink to “Subscribing to Standard Business Central Events”">​</a></h2><p>You don&#39;t have to create your own event publishers.</p><p>Business Central already provides many standard events that extensions can subscribe to.</p><p>For example, you can subscribe to the Customer table&#39;s <code>OnAfterInsertEvent</code>:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>codeunit 50102 CustomerTableSubscriber</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    [EventSubscriber(</span></span>
<span class="line"><span>        ObjectType::Table,</span></span>
<span class="line"><span>        Database::Customer,</span></span>
<span class="line"><span>        &#39;OnAfterInsertEvent&#39;,</span></span>
<span class="line"><span>        &#39;&#39;,</span></span>
<span class="line"><span>        false,</span></span>
<span class="line"><span>        false)]</span></span>
<span class="line"><span>    local procedure AfterCustomerInsert(</span></span>
<span class="line"><span>        var Rec: Record Customer;</span></span>
<span class="line"><span>        RunTrigger: Boolean)</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Message(&#39;A new customer was inserted: %1&#39;, Rec.Name);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This subscriber executes after a Customer record is inserted.</p><p>Unlike our custom Integration Event, this is a <strong>table trigger event</strong> raised automatically by Business Central.</p><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>An event subscriber listens for an event and contains the logic that should execute when that event occurs.</p><p>Remember:</p><ul><li>Publisher: Declares and raises the event.</li><li>Subscriber: Listens and responds to the event.</li><li>Event: The notification connecting them.</li></ul>`,26)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};